/* Function Kingdom · Math 138. Add questions and flashcards to the arrays below. */
const QUESTIONS = [
  {id:"p-sqrt",realm:"parents",prompt:"Which parent function is f(x) = √x?",context:"Name the family before you think about a transformation.",options:["Quadratic","Square root","Cube root","Absolute value"],answer:1,hint:"A radical sign with a small invisible index 2 gives this family its name.",explanation:"√x is the square-root parent. It begins at the origin and only accepts inputs x ≥ 0 in the real numbers.",takeaway:"Shape first, then domain and range.",graph:"sqrt"},
  {id:"p-sqrt-domain",realm:"parents",prompt:"What is the real domain of f(x) = √x?",context:"Domain means the allowed input values.",options:["All real numbers","x ≥ 0","x > 0","y ≥ 0"],answer:1,hint:"The expression under an even root cannot be negative when outputs are real.",explanation:"For real outputs, x under the square root must be at least zero. Zero is allowed because √0 = 0, so the domain is [0, ∞).",takeaway:"Square root: start at zero; include zero."},
  {id:"p-sqrt-range",realm:"parents",prompt:"What is the range of f(x) = √x?",context:"Range means the possible output values.",options:["y ≥ 0","y > 0","All real numbers","y ≤ 0"],answer:0,hint:"Can the principal square root of a nonnegative number be negative?",explanation:"The principal square root is never negative and can equal zero. The range is [0, ∞).",takeaway:"Domain is x; range is y."},
  {id:"p-parabola",realm:"parents",prompt:"Which formula matches this parent graph?",context:"Look for its vertex and symmetry.",options:["f(x) = |x|","f(x) = x²","f(x) = √x","f(x) = x³"],answer:1,hint:"This smooth U shape is symmetric about the y-axis.",explanation:"The smooth U-shaped parabola with vertex (0, 0) is the quadratic parent f(x) = x². Absolute value makes a sharp V.",takeaway:"Smooth U: x². Sharp V: |x|.",graph:"square"},
  {id:"p-absolute",realm:"parents",prompt:"A graph is a sharp V with vertex at the origin. Which parent is it?",context:"The two arms are straight line segments.",options:["f(x) = x²","f(x) = |x|","f(x) = 1/x","f(x) = √x"],answer:1,hint:"Negative inputs reflect up to positive outputs.",explanation:"The absolute-value parent f(x) = |x| has a sharp corner at (0, 0). Its domain is all real numbers and range is y ≥ 0.",takeaway:"A corner distinguishes |x| from x².",graph:"abs"},
  {id:"p-reciprocal",realm:"parents",prompt:"Which input must be excluded from f(x) = 1/x?",context:"A denominator cannot equal zero.",options:["x = −1","x = 0","x = 1","No input is excluded"],answer:1,hint:"Ask which number would make the denominator zero.",explanation:"At x = 0, 1/x is undefined. The reciprocal graph has two branches and a vertical asymptote at x = 0.",takeaway:"Reciprocal: exclude zero from the domain.",graph:"reciprocal"},
  {id:"p-exp",realm:"parents",prompt:"Which parent stays above the x-axis and passes through (0, 1)?",context:"It grows by repeated multiplication.",options:["f(x) = x²","f(x) = 2ˣ","f(x) = ln x","f(x) = 1/x"],answer:1,hint:"Any positive base raised to the zero power equals 1.",explanation:"The exponential parent 2ˣ passes through (0, 1), has all real inputs, and has positive outputs. y = 0 is a horizontal asymptote.",takeaway:"Exponential: (0, 1), output > 0.",graph:"exp"},
  {id:"p-cubic",realm:"parents",prompt:"What is the range of the cubic parent f(x) = x³?",context:"Picture its S shape extending down left and up right.",options:["y ≥ 0","y > 0","All real numbers","−1 ≤ y ≤ 1"],answer:2,hint:"As x becomes very negative or very positive, what happens to x³?",explanation:"x³ takes every real output. Its domain and range are both all real numbers.",takeaway:"Cubic: all real inputs and outputs.",graph:"cubic"},
  {id:"t-right-up",realm:"shifts",prompt:"Starting with f(x) = √x, what does g(x) = √(x − 3) + 2 do?",context:"Read the change inside first, then outside.",options:["Left 3, up 2","Right 3, up 2","Right 3, down 2","Left 3, down 2"],answer:1,hint:"Inside x − h moves the starting point to x = h.",explanation:"x − 3 shifts the graph right 3. The +2 outside shifts it up 2. Its new starting point is (3, 2).",takeaway:"Inside moves opposite the sign; outside follows the sign."},
  {id:"t-left",realm:"shifts",prompt:"Where is the vertex of g(x) = (x + 2)²?",context:"Use the quadratic parent x².",options:["(2, 0)","(−2, 0)","(0, 2)","(0, −2)"],answer:1,hint:"Rewrite x + 2 as x − (−2).",explanation:"The +2 is inside the parentheses, so the parabola shifts left 2. Its vertex is (−2, 0).",takeaway:"x + 2 means left 2."},
  {id:"t-reflect",realm:"shifts",prompt:"What does g(x) = −x² do to the parent y = x²?",context:"The minus sign is outside the square.",options:["Reflect across the x-axis","Reflect across the y-axis","Shift down 1","Shift left 1"],answer:0,hint:"Every output changes sign: y becomes −y.",explanation:"Multiplying the whole function by −1 reflects the parabola across the x-axis, so it opens downward.",takeaway:"Outside negative: flip vertically."},
  {id:"t-stretch",realm:"shifts",prompt:"Compared with y = |x|, what does y = 2|x| do?",context:"Compare the output at x = 1.",options:["Move up 2","Vertical stretch by 2","Horizontal stretch by 2","Move right 2"],answer:1,hint:"At x = 1, the parent outputs 1 and the new function outputs 2.",explanation:"The outside factor doubles every y-value. The V is steeper, a vertical stretch by factor 2.",takeaway:"Outside multiplier changes outputs."},
  {id:"t-compress",realm:"shifts",prompt:"What does g(x) = f(2x) do horizontally?",context:"The factor 2 is inside the function.",options:["Stretch by 2","Compress by 1/2","Move right 2","No change"],answer:1,hint:"To get the old output at x = 1, the new input only needs x = 1/2.",explanation:"Inputs reach the same parent-function values in half the x-distance, so f(2x) compresses horizontally by a factor of 1/2.",takeaway:"Inside multiplier works reciprocally."},
  {id:"t-vertex",realm:"shifts",prompt:"Where is the vertex of g(x) = (x − 1)² + 4?",context:"Use y = (x − h)² + k.",options:["(−1, 4)","(1, −4)","(1, 4)","(4, 1)"],answer:2,hint:"The squared part is zero at x = 1.",explanation:"The quadratic parent moves right 1 and up 4. Its vertex is (1, 4).",takeaway:"For (x − h)² + k, vertex = (h, k)."},
  {id:"t-domain",realm:"shifts",prompt:"What is the domain of g(x) = √(x + 4)?",context:"Find which inputs keep the radicand nonnegative.",options:["x ≥ 4","x > −4","x ≥ −4","All real numbers"],answer:2,hint:"Solve x + 4 ≥ 0, including equality.",explanation:"The radicand must satisfy x + 4 ≥ 0, so x ≥ −4. The graph begins at (−4, 0).",takeaway:"Shifted root domain: solve inside ≥ 0."},
  {id:"t-general",realm:"shifts",prompt:"In y = a·f(b(x − h)) + k, which symbol shifts the graph up or down?",context:"Read the part added after the whole function.",options:["a","b","h","k"],answer:3,hint:"This term is outside f and is added to every output.",explanation:"k adds the same amount to every y-value. Positive k shifts up; negative k shifts down.",takeaway:"k controls vertical position."},
  {id:"r-workflow",realm:"rates",prompt:"You need the tangent line to y = f(x) at x = a. What is the right workflow?",context:"A tangent line needs a point and a slope.",options:["Find f(a), find f′(a), then use y − f(a) = f′(a)(x − a)","Find f(a), then use it as the slope","Find f′(x), then set y = f′(x)","Find two distant points and connect them"],answer:0,hint:"The point is (a, f(a)); the tangent slope is f′(a).",explanation:"Evaluate f(a) for the point, evaluate f′(a) for the instantaneous slope, then write the point-slope equation.",takeaway:"Point from f; slope from f′."},
  {id:"r-derivative",realm:"rates",prompt:"If f(x) = x², what is the tangent slope at x = 3?",context:"The derivative gives slope at a single x-value.",options:["3","6","9","12"],answer:1,hint:"For x², f′(x) = 2x. Now substitute x = 3.",explanation:"f′(x) = 2x, so f′(3) = 6. The tangent line rises 6 units for each 1 unit of x near x = 3.",takeaway:"Differentiate, then evaluate."},
  {id:"r-secant",realm:"rates",prompt:"A line passes through (1, 2) and (3, 6). What is its slope?",context:"Use change in y divided by change in x.",options:["1/2","2","3","4"],answer:1,hint:"Compute (6 − 2) ÷ (3 − 1).",explanation:"The slope is (6 − 2)/(3 − 1) = 4/2 = 2. For a position graph, this would be average velocity over that interval.",takeaway:"Secant slope = average rate of change."},
  {id:"r-positive",realm:"rates",prompt:"On the position graph, what is the velocity from t = 0 to t = 2?",context:"Velocity is the slope of position versus time.",options:["Positive","Zero","Negative","Cannot tell"],answer:0,hint:"The position graph rises as time increases.",explanation:"Position increases from t = 0 to 2, so the slope and velocity are positive. The object moves in the positive direction.",takeaway:"Rising position → positive velocity.",graph:"position"},
  {id:"r-zero",realm:"rates",prompt:"On the position graph, what is the velocity from t = 2 to t = 4?",context:"Look at the middle segment.",options:["Positive","Zero","Negative","Cannot tell"],answer:1,hint:"A horizontal segment has slope 0.",explanation:"Position stays constant from t = 2 to 4, so velocity is zero: the object is stopped during that interval.",takeaway:"Flat position → zero velocity.",graph:"position"},
  {id:"r-negative",realm:"rates",prompt:"On the position graph, what is the velocity from t = 4 to t = 6?",context:"Look at the final segment.",options:["Positive","Zero","Negative","Cannot tell"],answer:2,hint:"The position graph falls as time increases.",explanation:"Position decreases from t = 4 to 6, so slope and velocity are negative. The object moves in the negative direction.",takeaway:"Falling position → negative velocity.",graph:"position"},
  {id:"r-units",realm:"rates",prompt:"Position is measured in meters and time in seconds. What are velocity's units?",context:"Rate units come from output units divided by input units.",options:["Meters","Seconds","Meters per second","Seconds per meter"],answer:2,hint:"Velocity = change in position ÷ change in time.",explanation:"A slope on a position-versus-time graph has units meters/second. Always carry units into a rate interpretation.",takeaway:"Rate units = vertical units / horizontal units."},
  {id:"r-instant",realm:"rates",prompt:"What does f′(a) mean on a position-versus-time graph?",context:"Think about a tangent line at one moment.",options:["Position at every time","Average velocity for the whole trip","Instantaneous velocity at time a","Total distance traveled"],answer:2,hint:"A derivative is the limiting slope of secant lines near t = a.",explanation:"f′(a) is the tangent slope at time a: instantaneous velocity. A secant slope over an interval gives average velocity.",takeaway:"Tangent = instant; secant = interval."},
  {id:"f-gcf",realm:"factoring",prompt:"What is the first useful step for 6x² + 9x?",context:"Step 1 · Check for a greatest common factor (GCF).",options:["Factor out 3x","Use difference of squares","Cancel x from one term","Factor out 9x"],answer:0,hint:"Both terms share 3 and at least one x.",explanation:"Both 6x² and 9x are divisible by 3x, giving 3x(2x + 3). Check: 3x·2x + 3x·3 = 6x² + 9x.",takeaway:"Always look for a GCF first."},
  {id:"f-gcf-then",realm:"factoring",prompt:"After extracting the GCF from 4x² − 16, what remains?",context:"Step 1 first; a second pattern may appear inside.",options:["4(x² − 4)","4(x − 4)","(4x − 4)(x + 4)","4x(x − 4)"],answer:0,hint:"Divide both terms by 4: 4x²/4 and −16/4.",explanation:"4x² − 16 = 4(x² − 4). The inside is then a difference of squares: x² − 2² = (x − 2)(x + 2).",takeaway:"GCF can uncover the next pattern."},
  {id:"f-squares",realm:"factoring",prompt:"How does x² − 25 factor?",context:"Step 2 · Difference of squares: A² − B².",options:["(x − 5)²","(x − 5)(x + 5)","(x − 25)(x + 1)","It does not factor"],answer:1,hint:"25 = 5². The middle terms should cancel on multiplication.",explanation:"x² − 5² = (x − 5)(x + 5). Multiplying gives x² + 5x − 5x − 25 = x² − 25.",takeaway:"A² − B² = (A − B)(A + B)."},
  {id:"f-tri-pair",realm:"factoring",prompt:"For x² + 5x + 6, which two numbers should you seek?",context:"Step 3 · For x² + bx + c, multiply to c and add to b.",options:["1 and 6","2 and 3","−2 and −3","5 and 6"],answer:1,hint:"Find numbers whose product is 6 and sum is 5.",explanation:"2·3 = 6 and 2 + 3 = 5. That pair fills (x + 2)(x + 3).",takeaway:"Monic trinomial: product c, sum b."},
  {id:"f-tri-factor",realm:"factoring",prompt:"Which factorization rebuilds x² + 5x + 6?",context:"Use the pair from the previous step, then multiply to check.",options:["(x + 1)(x + 6)","(x − 2)(x − 3)","(x + 2)(x + 3)","(x + 5)(x + 6)"],answer:2,hint:"Try 2 and 3; the cross terms become 2x and 3x.",explanation:"(x + 2)(x + 3) = x² + 3x + 2x + 6 = x² + 5x + 6. The check confirms all three coefficients.",takeaway:"Multiply the factors back to verify."},
  {id:"f-ac",realm:"factoring",prompt:"For 2x² + 7x + 3, what pair starts the ac method?",context:"Step 4 · When a ≠ 1, multiply a·c before looking for the pair.",options:["2 and 3","6 and 1","7 and 3","−6 and −1"],answer:1,hint:"a·c = 2·3 = 6; which factors of 6 add to 7?",explanation:"6 and 1 multiply to 6 and add to 7. Split the middle term as 6x + x: 2x² + 6x + x + 3.",takeaway:"When a ≠ 1: product ac, sum b."},
  {id:"f-group",realm:"factoring",prompt:"How does 2x² + 6x + x + 3 group into factors?",context:"Continue the ac-method example after splitting 7x.",options:["(2x + 1)(x + 3)","(2x + 3)(x + 1)","(2x − 1)(x − 3)","(x + 1)(x + 3)"],answer:0,hint:"Group as 2x(x + 3) + 1(x + 3).",explanation:"Factor each pair: 2x(x + 3) + (x + 3). The common binomial gives (2x + 1)(x + 3).",takeaway:"Split, group, extract the shared binomial."},
  {id:"f-foil",realm:"factoring",prompt:"Which expansion verifies (2x + 1)(x + 3)?",context:"Step 5 · Check with distribution or FOIL.",options:["2x² + 3x + 3","2x² + 7x + 3","2x² + 6x + 1","2x² + 7x + 1"],answer:1,hint:"Multiply: 2x·x, 2x·3, 1·x, and 1·3.",explanation:"2x² + 6x + x + 3 = 2x² + 7x + 3. The middle terms are easy to miss; always combine them.",takeaway:"FOIL is the reverse check for factoring."},
  {id:"f-limit",realm:"factoring",prompt:"Before finding limₓ→₃ (x² − 9)/(x − 3), what should you do?",context:"Calculus connection · Direct substitution gives 0/0, so simplify the expression for x ≠ 3.",options:["Cancel only the x's","Factor x² − 9, then cancel the common (x − 3) factor","Say the limit is undefined","Differentiate the numerator only"],answer:1,hint:"x² − 9 is a difference of squares.",explanation:"x² − 9 = (x − 3)(x + 3). For x ≠ 3, the quotient simplifies to x + 3. The original expression is undefined at 3, but its limit is 6.",takeaway:"Cancel common factors, never isolated terms."},
  {id:"q2-left2",realm:"quiz",stage:"graph",prompt:"From the graph, what is limₓ→₂⁻ g(x)?",context:"Approach x = 2 from values smaller than 2. Follow the curve, not the filled point.",options:["0","1","2","DNE"],answer:2,hint:"The left branch approaches the upper open circle at (2, 2).",explanation:"As x approaches 2 from the left, the curve approaches y = 2. The filled dot at y = 1 tells g(2), not this limit.",takeaway:"Open circle can still show an approached value.",graph:"quizG"},
  {id:"q2-right2",realm:"quiz",stage:"graph",prompt:"From the graph, what is limₓ→₂⁺ g(x)?",context:"Approach x = 2 from values greater than 2.",options:["0","1","2","DNE"],answer:0,hint:"The right branch begins at the lower open circle on the x-axis.",explanation:"As x approaches 2 from the right, g(x) approaches 0. This is different from the left-hand limit of 2.",takeaway:"Right-hand limit follows the right branch.",graph:"quizG"},
  {id:"q2-both2",realm:"quiz",stage:"graph",prompt:"Does limₓ→₂ g(x) exist?",context:"A two-sided limit requires left and right to agree.",options:["Yes, 0","Yes, 1","Yes, 2","No, DNE"],answer:3,hint:"Compare the two open-circle heights at x = 2.",explanation:"The left-hand limit is 2 while the right-hand limit is 0. Because they disagree, the two-sided limit does not exist.",takeaway:"Two-sided limit exists only when both sides match.",graph:"quizG"},
  {id:"q2-value2",realm:"quiz",stage:"graph",prompt:"What is g(2) on the graph?",context:"A function value is the filled point at that x.",options:["0","1","2","DNE"],answer:1,hint:"Find the solid dot at x = 2, between the two open circles.",explanation:"The filled dot is at (2, 1), so g(2) = 1. Neither one-sided limit needs to equal that value.",takeaway:"Filled dot = function value.",graph:"quizG"},
  {id:"q2-left0",realm:"quiz",stage:"graph",prompt:"From the graph, what is limₓ→₀⁻ g(x)?",context:"Approach x = 0 from negative x-values.",options:["−2","−1","0","DNE"],answer:1,hint:"The left branch ends at a solid dot at y = −1.",explanation:"The left branch approaches y = −1 as x approaches 0 from the left. Here the left-hand limit happens to equal g(0).",takeaway:"Read the side named by the superscript.",graph:"quizG"},
  {id:"q2-right0",realm:"quiz",stage:"graph",prompt:"From the graph, what is limₓ→₀⁺ g(x)?",context:"Approach x = 0 from positive x-values.",options:["−2","−1","0","DNE"],answer:0,hint:"The right-side curve starts at an open circle at y = −2.",explanation:"From the right, g(x) approaches −2. The open circle is not g(0), but it does determine this one-sided limit.",takeaway:"Approached height can differ from the point value.",graph:"quizG"},
  {id:"q2-both0",realm:"quiz",stage:"graph",prompt:"What is limₓ→₀ g(x)?",context:"Compare the left and right approaches at x = 0.",options:["−2","−1","0","DNE"],answer:3,hint:"One branch approaches −1; the other approaches −2.",explanation:"The one-sided limits are −1 and −2, so they do not agree. The two-sided limit is DNE, even though g(0) is defined.",takeaway:"Defined point does not guarantee a limit.",graph:"quizG"},
  {id:"q2-value0",realm:"quiz",stage:"graph",prompt:"What is g(0) on the graph?",context:"Find the solid point at x = 0.",options:["−2","−1","0","DNE"],answer:1,hint:"At x = 0, the solid point is one unit below the x-axis.",explanation:"The solid point is (0, −1), so g(0) = −1. The open point at (0, −2) belongs to the right-hand approach only.",takeaway:"For g(a), read the solid dot.",graph:"quizG"},
  {id:"q2-law1",realm:"quiz",stage:"laws",prompt:"Find limₓ→₂ [3f(x) + 5g(x)] from the paired graphs.",context:"At x → 2, f approaches −1 and g approaches 2.",options:["−3","7","11","DNE"],answer:1,hint:"Apply limit laws to the approached values: 3(−1) + 5(2).",explanation:"3·(−1) + 5·2 = −3 + 10 = 7. Use the limiting heights, including the hole on f, not an actual point value.",takeaway:"Read each limit first, then combine.",graph:"quizPair"},
  {id:"q2-law2",realm:"quiz",stage:"laws",prompt:"Find limₓ→₃ [2f(x) − 4g(x)] from the paired graphs.",context:"At x → 3, f approaches 1 and g approaches 0.",options:["−2","0","2","4"],answer:2,hint:"Compute 2(1) − 4(0).",explanation:"The limit is 2·1 − 4·0 = 2. A coefficient multiplies the whole limiting value.",takeaway:"Scalar and difference laws work when component limits exist.",graph:"quizPair"},
  {id:"q2-law3",realm:"quiz",stage:"laws",prompt:"Find limₓ→₀⁻ [g(x)]² from the paired graphs.",context:"The left branch of g approaches 3 at x = 0.",options:["1","3","9","DNE"],answer:2,hint:"Square the approached value: 3².",explanation:"As x approaches 0 from the left, g(x) approaches 3, so [g(x)]² approaches 9. The right-side branch approaches a different value.",takeaway:"Take the one-sided limit before squaring.",graph:"quizPair"},
  {id:"q2-law4",realm:"quiz",stage:"laws",prompt:"Find limₓ→₀ [4f(x)] from the paired graphs.",context:"The f graph approaches 2 from both sides at x = 0.",options:["2","4","8","DNE"],answer:2,hint:"Multiply the limit of f by 4.",explanation:"limₓ→₀ f(x) = 2, so limₓ→₀ 4f(x) = 4·2 = 8.",takeaway:"Constant multiple law: move the constant outside.",graph:"quizPair"},
  {id:"q2-direct",realm:"quiz",stage:"methods",prompt:"Which method should start limₓ→₂ (2x³ − x + 6)/(5x)?",context:"Check the denominator at the target before doing algebra.",options:["Direct substitution","Rationalize","Factor and cancel","Declare DNE"],answer:0,hint:"At x = 2, the denominator is 10, not zero.",explanation:"The rational expression is continuous at x = 2 because 5x ≠ 0 there. Substitute: (16 − 2 + 6)/10 = 2.",takeaway:"Try substitution first; continue only if it fails."},
  {id:"q2-rationalize",realm:"quiz",stage:"methods",prompt:"What is the best first repair for limₓ→₀ (√(15x + 1) − 1)/x?",context:"Direct substitution gives 0/0 and the numerator contains a radical.",options:["Multiply by the conjugate","Cancel the x inside the root","Set the limit to zero","Use difference of squares on x"],answer:0,hint:"Pair √(15x + 1) − 1 with √(15x + 1) + 1.",explanation:"Multiply top and bottom by the conjugate. The numerator becomes (15x + 1) − 1 = 15x; cancel x for x ≠ 0. The limit is 15/(1 + 1) = 15/2.",takeaway:"Radical 0/0 → try the conjugate."},
  {id:"q2-factorlimit",realm:"quiz",stage:"methods",prompt:"What is the useful factorization for (x² − 1)/(2x² − 2x) as x → 1?",context:"Direct substitution gives 0/0. Factor numerator and denominator completely.",options:["(x − 1)(x + 1) / [2x(x − 1)]","(x − 1)² / [2x(x − 1)]","(x + 1) / 2x²","x(x − 1) / [2(x + 1)]"],answer:0,hint:"Use difference of squares above and GCF 2x below.",explanation:"x² − 1 = (x − 1)(x + 1) and 2x² − 2x = 2x(x − 1). Cancel the common (x − 1) for x ≠ 1, then (x + 1)/(2x) approaches 1.",takeaway:"Factor both parts; cancel a whole shared factor."},
  {id:"q2-oscillate",realm:"quiz",stage:"methods",prompt:"What happens to limₓ→₀ sin(π/x)?",context:"Near zero, π/x changes without bound.",options:["It approaches 0","It approaches 1","It approaches −1","It does not exist"],answer:3,hint:"The sine values keep swinging between −1 and 1 arbitrarily near x = 0.",explanation:"As x approaches zero, sin(π/x) oscillates indefinitely and never settles at one height. Its limit does not exist.",takeaway:"Bounded does not mean convergent."},
  {id:"q2-sketch-square",realm:"quiz",stage:"parents",prompt:"Which sketch facts are correct for y = x²?",context:"Name the vertex, intercept, domain, and range.",options:["Downward U; range y ≤ 0","Smooth upward U; vertex and both intercepts at (0, 0); range y ≥ 0","Sharp V; range y ≥ 0","Two branches; x = 0 asymptote"],answer:1,hint:"Squaring any real x is nonnegative, and x = 0 gives y = 0.",explanation:"y = x² is a smooth upward parabola with vertex (0, 0). Domain is all real numbers; range is y ≥ 0; both intercepts are (0, 0).",takeaway:"Sketch from anchor point, shape, and range.",graph:"square"},
  {id:"q2-sketch-exp",realm:"quiz",stage:"parents",prompt:"Which anchors correctly sketch y = eˣ?",context:"Think about x = 0 and what happens far to the left.",options:["Through (0, 0); vertical asymptote x = 0","Through (0, 1); horizontal asymptote y = 0; no x-intercept","Through (1, 0); vertical asymptote x = 0","Two branches; both axes asymptotes"],answer:1,hint:"e⁰ = 1, and eˣ is always positive.",explanation:"The exponential rises through (0, 1), never reaches y = 0, and approaches the horizontal asymptote y = 0 as x → −∞. Domain is all real; range is (0, ∞).",takeaway:"eˣ: (0, 1), no x-intercept, y = 0 asymptote.",graph:"expE"},
  {id:"q2-sketch-recip",realm:"quiz",stage:"parents",prompt:"Which description sketches y = 1/x?",context:"Check excluded inputs and whether it crosses either axis.",options:["One U-shaped branch through the origin","Two branches in quadrants I and III; x = 0 and y = 0 asymptotes; no intercepts","A V with vertex at the origin","An increasing curve through (0, 1)"],answer:1,hint:"At x = 0 it is undefined, and 1/x can never equal zero.",explanation:"The reciprocal has branches in quadrants I and III. x = 0 is a vertical asymptote, y = 0 a horizontal one; neither axis is crossed. Domain and range exclude zero.",takeaway:"1/x: two branches, two axis asymptotes, no intercepts.",graph:"reciprocal"},
  {id:"q2-sketch-log",realm:"quiz",stage:"parents",prompt:"Which anchors correctly sketch y = ln x?",context:"Find its allowed inputs and the point where its output is zero.",options:["Through (0, 1); y = 0 asymptote","Through (1, 0); vertical asymptote x = 0; no y-intercept","Through (0, 0); range y ≥ 0","Two branches; x = 0 excluded but y = 0 excluded"],answer:1,hint:"ln(1) = 0, and ln x needs x > 0.",explanation:"ln x is defined only for x > 0, crosses the x-axis at (1, 0), has no y-intercept, and approaches a vertical asymptote at x = 0. Its range is all real.",takeaway:"ln x: (1, 0), x > 0, x = 0 asymptote.",graph:"log"},
  {id:"n-hole-limit",realm:"notes",stage:"approach",prompt:"Let g(x) = x + 1 when x ≠ 1, but g(1) = 7. What is limₓ→₁ g(x)?",context:"Class-note idea · A limit follows nearby inputs, not the value at the point.",options:["2","7","1","DNE"],answer:0,hint:"For every x near 1 except 1, g(x) = x + 1.",explanation:"Nearby values follow x + 1 and approach 2. The isolated filled point g(1) = 7 does not change the limit.",takeaway:"Limit reads the approach; g(1) reads the point."},
  {id:"n-hole-value",realm:"notes",stage:"approach",prompt:"For that same g, what is g(1)?",context:"g(x) = x + 1 for x ≠ 1, while the rule explicitly says g(1) = 7.",options:["2","7","1","DNE"],answer:1,hint:"Use the special rule at x = 1, not the surrounding formula.",explanation:"The piecewise definition assigns g(1) = 7. Its limit is 2, so the function is discontinuous at 1.",takeaway:"A filled-point value can differ from the limit."},
  {id:"n-poly",realm:"notes",stage:"approach",prompt:"What is limₓ→₂ (x² − x + 2)?",context:"Decision step 1 · Try direct substitution for a polynomial.",options:["2","3","4","DNE"],answer:2,hint:"Compute 2² − 2 + 2.",explanation:"Polynomials are continuous, so substitute x = 2: 4 − 2 + 2 = 4. No factoring or other repair is needed.",takeaway:"Continuous formula? Substitute first."},
  {id:"n-abs-distance",realm:"notes",stage:"approach",prompt:"What does |x| represent on the number line?",context:"This meaning predicts the shape and one-sided behavior.",options:["A signed direction","Distance from 0, always nonnegative","The same output as x for every x","A quotient"],answer:1,hint:"Distance cannot be negative.",explanation:"|x| is the distance of x from zero. It equals x when x ≥ 0 and −x when x < 0.",takeaway:"Absolute value is nonnegative distance."},
  {id:"n-abs-sides",realm:"notes",stage:"approach",prompt:"For |x|/x near 0, which one-sided limits are correct?",context:"Use the piecewise rule for absolute value.",options:["Left 1, right 1","Left −1, right 1","Left 0, right 0","Left 1, right −1"],answer:1,hint:"For x < 0, |x| = −x; for x > 0, |x| = x.",explanation:"On the left, |x|/x = −x/x = −1. On the right, it is x/x = 1. Since these differ, the two-sided limit at 0 is DNE.",takeaway:"One-sided disagreement means DNE."},
  {id:"n-factor-one",realm:"notes",stage:"repair",prompt:"Direct substitution gives 0/0 for (x² − 1)/(x − 1) as x → 1. What repairs it?",context:"Look for a complete common factor.",options:["Cancel the x terms","Factor x² − 1 as (x − 1)(x + 1), then cancel x − 1","Rationalize the denominator","Declare DNE"],answer:1,hint:"Use A² − B² with A = x and B = 1.",explanation:"For x ≠ 1, (x² − 1)/(x − 1) = (x − 1)(x + 1)/(x − 1) = x + 1. Its limit is 2 although the original quotient is undefined at 1.",takeaway:"Factor, cancel a whole factor, then substitute."},
  {id:"n-factor-two",realm:"notes",stage:"repair",prompt:"How do you simplify (x − 4)/(x² − 16) before x → 4?",context:"The denominator is a difference of squares.",options:["1/(x + 4) for x ≠ 4","1/(x − 4)","x + 4","0"],answer:0,hint:"x² − 16 = (x − 4)(x + 4).",explanation:"Cancel the common (x − 4) factor for x ≠ 4, leaving 1/(x + 4). The limit as x → 4 is 1/8.",takeaway:"Factoring may be needed below the fraction bar."},
  {id:"n-conjugate",realm:"notes",stage:"repair",prompt:"What does rationalizing (√(t² + 9) − 3)/t² reveal as t → 0?",context:"A radical numerator and 0/0 suggest the conjugate.",options:["1/(√(t² + 9) + 3), giving 1/6","t/(√(t² + 9) + 3), giving 0","√(t² + 9) + 3, giving 6","DNE"],answer:0,hint:"Multiply by √(t² + 9) + 3; the numerator becomes t².",explanation:"The conjugate gives [(t² + 9) − 9]/[t²(√(t² + 9) + 3)]. Cancel t² for t ≠ 0, then substitute to get 1/(3 + 3) = 1/6.",takeaway:"Conjugate changes a radical difference into a factor."},
  {id:"n-method-tree",realm:"notes",stage:"repair",prompt:"After direct substitution produces 0/0, what should you inspect next?",context:"Choose an algebraic repair based on the expression's structure.",options:["Always answer zero","Factor polynomials or use a conjugate for radicals","Ignore the denominator","Always differentiate"],answer:1,hint:"Match the repair to what causes the 0/0 form.",explanation:"A polynomial quotient may hide a common factor; a radical difference may simplify with a conjugate. Simplify for nearby inputs, then substitute again.",takeaway:"0/0 is a signal to investigate, not an answer."},
  {id:"n-squeeze",realm:"notes",stage:"behavior",prompt:"Why does limₓ→₀ x² sin(1/x) equal 0?",context:"The sine oscillates, but its amplitude is trapped by x².",options:["sin(1/x) itself tends to 0","−x² ≤ x² sin(1/x) ≤ x² and both bounds tend to 0","x² is undefined at 0","The product always equals 0"],answer:1,hint:"Start with −1 ≤ sin(1/x) ≤ 1; multiply by nonnegative x².",explanation:"Because −x² and x² both approach 0, the squeezed middle expression also approaches 0. Oscillation alone does not force DNE when the amplitude shrinks.",takeaway:"Shrinking bounds can tame oscillation."},
  {id:"n-infinite-sides",realm:"notes",stage:"behavior",prompt:"How does 1/x behave near x = 0?",context:"A vertical asymptote can have different one-sided infinite behavior.",options:["Both sides approach +∞","Left → −∞, right → +∞","Both sides approach 0","Left → +∞, right → −∞"],answer:1,hint:"The sign of 1/x matches the sign of x.",explanation:"As x → 0⁻, 1/x decreases without bound; as x → 0⁺, it increases without bound. x = 0 is a vertical asymptote, and there is no finite two-sided limit.",takeaway:"Check signs on each side of a vertical asymptote."},
  {id:"n-recip-infinity",realm:"notes",stage:"behavior",prompt:"What happens to 1/x as x → +∞ or x → −∞?",context:"Now the input moves far away rather than toward zero.",options:["It approaches 0 from the appropriate sign","It grows to +∞ both ways","It approaches 1","It oscillates"],answer:0,hint:"A fixed numerator divided by a huge magnitude becomes tiny.",explanation:"1/x approaches 0 from above at +∞ and from below at −∞. The horizontal asymptote is y = 0.",takeaway:"Reciprocal near 0 blows up; far away it fades to 0."},
  {id:"n-exp-infinity",realm:"notes",stage:"behavior",prompt:"Which end behavior is correct for eˣ?",context:"Exponential growth and decay have different directions.",options:["x → +∞ gives 0; x → −∞ gives +∞","x → +∞ gives +∞; x → −∞ gives 0","Both directions give 0","Both directions give DNE"],answer:1,hint:"e^(−large) = 1/e^(large).",explanation:"eˣ grows without bound as x → +∞ and approaches 0 from above as x → −∞. y = 0 is its horizontal asymptote on the left.",takeaway:"Exponential right grows; left decays."},
  {id:"n-leading",realm:"notes",stage:"behavior",prompt:"What is limₓ→∞ (3x² + x)/(2x² − 5)?",context:"Compare dominant powers when x grows without bound.",options:["0","3/2","∞","DNE"],answer:1,hint:"Divide top and bottom by x².",explanation:"After division by x², the lower-order terms become 1/x and 5/x², both tending to 0. The leading-coefficient ratio is 3/2.",takeaway:"Equal top powers → ratio of leading coefficients."},
  {id:"n-sin-infinity",realm:"notes",stage:"behavior",prompt:"Does limₓ→∞ sin x exist?",context:"The input grows, but the output keeps cycling.",options:["Yes, 0","Yes, 1","Yes, −1","No, DNE"],answer:3,hint:"sin x continues to reach 1, 0, and −1 indefinitely.",explanation:"Sine keeps oscillating at full amplitude as x increases; it never settles at one value. This differs from x² sin(1/x), whose amplitude shrinks near zero.",takeaway:"Oscillation with no shrinking envelope gives DNE."},
  {id:"n-deriv-x",realm:"notes",stage:"tangent",prompt:"Which limit defines the tangent slope to y = f(x) at x = a?",context:"Start from secant slopes through (a, f(a)).",options:["limₓ→ₐ [f(x) − f(a)]/(x − a)","limₓ→ₐ f(x)/(x − a)","f(a)/(x − a)","limₓ→ₐ [f(x) + f(a)]"],answer:0,hint:"Slope is change in output divided by change in input.",explanation:"The secant slope is [f(x) − f(a)]/(x − a). Taking x → a gives the tangent slope when the limit exists.",takeaway:"Derivative = limiting secant slope."},
  {id:"n-deriv-h",realm:"notes",stage:"tangent",prompt:"Which h-form is equivalent to the tangent-slope limit at x = a?",context:"Let h = x − a, so x = a + h and h → 0.",options:["limₕ→₀ [f(a + h) − f(a)]/h","limₕ→₀ f(a + h)/a","limₕ→₀ [f(a) − f(h)]/a","f(a + h) − f(a)"],answer:0,hint:"Replace x with a + h in the numerator and x − a with h.",explanation:"The same secant slope becomes [f(a + h) − f(a)]/h. Taking h → 0 gives f′(a).",takeaway:"x-form and h-form describe the same tangent slope."},
  {id:"n-slope-three",realm:"notes",stage:"tangent",prompt:"Using f(x) = x² at a = 3, what are the tangent point and slope?",context:"Find f(3), then evaluate f′(3).",options:["Point (3, 6), slope 9","Point (3, 9), slope 6","Point (6, 9), slope 3","Point (3, 9), slope 9"],answer:1,hint:"f(3) = 9; f′(x) = 2x.",explanation:"The point is (3, f(3)) = (3, 9). The derivative is 2x, so the tangent slope at 3 is 6.",takeaway:"Point from f; slope from f′."},
  {id:"n-tangent-line",realm:"notes",stage:"tangent",prompt:"Which tangent-line equation follows for y = x² at x = 3?",context:"Use the point (3, 9) and slope 6.",options:["y − 9 = 6(x − 3)","y − 6 = 9(x − 3)","y = 6x² + 9","y − 3 = 6(x − 9)"],answer:0,hint:"Point-slope form is y − y₁ = m(x − x₁).",explanation:"Substitute m = 6 and (x₁, y₁) = (3, 9): y − 9 = 6(x − 3), or y = 6x − 9.",takeaway:"Tangent line needs both the point and the derivative slope."}
];

const FLASHCARDS = [
  {group:"Parents",front:"√x: what is its shape, domain, and range?",back:"Starts at (0, 0), curves right and up. Domain [0, ∞); range [0, ∞).",question:"p-sqrt-domain"},
  {group:"Parents",front:"x² versus |x|: how can you tell them apart?",back:"Both have vertex (0, 0) and outputs ≥ 0. x² is a smooth U; |x| is a sharp V.",question:"p-parabola"},
  {group:"Parents",front:"x³: domain, range, and silhouette?",back:"All real inputs and outputs; a smooth S through the origin.",question:"p-cubic"},
  {group:"Parents",front:"1/x: what is forbidden?",back:"x = 0 is excluded. Two branches approach x = 0 and y = 0 without touching the axes.",question:"p-reciprocal"},
  {group:"Parents",front:"2ˣ versus ln x: which has input x > 0?",back:"ln x has domain x > 0. Exponential 2ˣ has all real inputs and positive outputs.",question:"p-exp"},
  {group:"Parents",front:"Memory trail: Flat, Line, Bowl, Root, V, S, Sideways S, Rocket, Log, Split",back:"Constant, identity, quadratic, square root, absolute value, cubic, cube root, exponential, logarithm, reciprocal. Recall each silhouette as you say the trail.",question:"p-sqrt"},
  {group:"Shifts",front:"In y = a·f(b(x − h)) + k, what do h and k do?",back:"h shifts horizontally (right for positive h); k shifts vertically (up for positive k).",question:"t-right-up"},
  {group:"Shifts",front:"What does a negative outside f do?",back:"Reflects across the x-axis: y = −f(x) changes the sign of every output.",question:"t-reflect"},
  {group:"Shifts",front:"What does f(2x) do?",back:"Compresses horizontally by 1/2. Inside multipliers act reciprocally on x-distances.",question:"t-compress"},
  {group:"Shifts",front:"How do you find the domain of √(x + 4)?",back:"Set the inside ≥ 0: x + 4 ≥ 0, so x ≥ −4.",question:"t-domain"},
  {group:"Rates",front:"Tangent line recipe at x = a?",back:"Find point (a, f(a)); find slope f′(a); use y − f(a) = f′(a)(x − a).",question:"r-workflow"},
  {group:"Rates",front:"Secant slope versus tangent slope?",back:"Secant across an interval = average rate. Tangent at a point = instantaneous rate (derivative).",question:"r-instant"},
  {group:"Rates",front:"If position rises, flattens, then falls, what happens to velocity?",back:"Positive, then zero, then negative. Velocity is the slope of the position graph.",question:"r-positive"},
  {group:"Rates",front:"How do you get rate units from a graph?",back:"Divide vertical-axis units by horizontal-axis units. Position in meters over time in seconds gives m/s.",question:"r-units"},
  {group:"Factoring",front:"Factoring memory route: G → P → C",back:"GCF first. Pattern next (difference of squares or trinomial). Check by multiplying back. For a limit, cancel only a common factor.",question:"f-gcf"},
  {group:"Factoring",front:"What is the difference-of-squares pattern?",back:"A² − B² = (A − B)(A + B). The opposite middle terms cancel when you multiply.",question:"f-squares"},
  {group:"Factoring",front:"How do you factor x² + bx + c?",back:"Find two numbers that multiply to c and add to b, then use (x + m)(x + n).",question:"f-tri-pair"},
  {group:"Factoring",front:"What changes when a ≠ 1 in ax² + bx + c?",back:"Find numbers whose product is ac and sum is b. Split bx with that pair, then factor by grouping.",question:"f-ac"},
  {group:"Factoring",front:"How does FOIL confirm a factorization?",back:"Multiply every term in one factor by every term in the other, combine like terms, and compare all coefficients to the original.",question:"f-foil"},
  {group:"Factoring",front:"Why factor before evaluating some limits?",back:"A 0/0 substitution may hide a common factor. Factor and cancel for nearby x values, then evaluate the simplified expression's limit.",question:"f-limit"},
  {group:"Quiz 2",front:"At a jump, how do left, right, two-sided limit, and g(a) differ?",back:"Follow each side toward a. The two-sided limit exists only if those heights match. g(a) is the filled dot, which may be different.",question:"q2-both2"},
  {group:"Quiz 2",front:"At x = 2 on the Quiz 2 graph: left limit, right limit, g(2)?",back:"Left limit 2, right limit 0, filled point g(2) = 1. The two-sided limit is DNE.",question:"q2-value2"},
  {group:"Quiz 2",front:"At x = 0 on the Quiz 2 graph: left limit, right limit, g(0)?",back:"Left limit −1, right limit −2, filled point g(0) = −1. The two-sided limit is DNE.",question:"q2-both0"},
  {group:"Quiz 2",front:"How do limit laws work on two graphs?",back:"Read each function's approached value first, then apply constants, sums, differences, and powers. Do not substitute the filled point for a limit.",question:"q2-law1"},
  {group:"Quiz 2",front:"Limit method decision: direct, factor, or rationalize?",back:"Try substitution. If denominator stays nonzero, stop. If 0/0: factor polynomials or conjugate a radical numerator; simplify, then substitute again.",question:"q2-rationalize"},
  {group:"Quiz 2",front:"Why does sin(π/x) have no limit as x → 0?",back:"Its values oscillate between −1 and 1 ever faster. They never settle toward one number.",question:"q2-oscillate"},
  {group:"Quiz 2",front:"Four parent sketch anchors: x², eˣ, 1/x, ln x",back:"x²: smooth U through (0,0). eˣ: (0,1), y=0 asymptote. 1/x: two branches, both axes asymptotes. ln x: (1,0), x=0 asymptote.",question:"q2-sketch-log"},
  {group:"Class Notes",front:"Decision route for a finite limit?",back:"Substitute first. If 0/0, factor a polynomial or conjugate a radical. If one-sided approaches differ, DNE. If oscillation is squeezed by bounds tending to zero, use squeeze.",question:"n-method-tree"},
  {group:"Class Notes",front:"A hole at x = 1 follows x + 1 nearby, but g(1) = 7. What are limit and point value?",back:"limₓ→₁ g(x) = 2 from nearby values; g(1) = 7 from the special definition.",question:"n-hole-limit"},
  {group:"Class Notes",front:"Why does |x|/x have no two-sided limit at zero?",back:"For x < 0 it equals −1; for x > 0 it equals 1. The one-sided limits disagree.",question:"n-abs-sides"},
  {group:"Class Notes",front:"Rationalize (√(t²+9)−3)/t²: what remains?",back:"Multiply by the conjugate; t² cancels, leaving 1/(√(t²+9)+3). The limit is 1/6.",question:"n-conjugate"},
  {group:"Class Notes",front:"Why does x² sin(1/x) tend to zero near x = 0?",back:"It lies between −x² and x². Both bounds approach zero, so the squeeze theorem forces the middle to zero.",question:"n-squeeze"},
  {group:"Class Notes",front:"1/x: behavior near zero versus at infinity?",back:"Near 0: left → −∞, right → +∞. At ±∞: values approach 0 from the corresponding sign.",question:"n-infinite-sides"},
  {group:"Class Notes",front:"Rational functions at infinity: equal highest powers?",back:"Divide by the highest power. When numerator and denominator degrees match, use the ratio of their leading coefficients.",question:"n-leading"},
  {group:"Class Notes",front:"Two equivalent derivative definitions at a?",back:"limₓ→ₐ [f(x)−f(a)]/(x−a) and limₕ→₀ [f(a+h)−f(a)]/h. Both are limiting secant slopes.",question:"n-deriv-h"},
  {group:"Class Notes",front:"Tangent line to x² at x = 3?",back:"Point (3,9), slope 6, so y−9 = 6(x−3). Use f for the point and f′ for slope.",question:"n-tangent-line"}
];

const REALMS = {
  quiz:{title:"Quiz 2 Recovery",icon:"🧭",tag:"Featured · Rebuild",description:"Replay the graph, limit laws, method choices, and parent sketches from your quiz.",color:"#ffd166"},
  notes:{title:"Notes Lab",icon:"📓",tag:"Guided · Connect",description:"Turn class notes into a limit decision tree, then link it to tangent lines.",color:"#8fb9ff"},
  parents:{title:"Parent Grove",icon:"🌿",tag:"Realm I · Recognize",description:"Match formulas, shapes, domains, and ranges before adding any changes.",color:"#73e0c4"},
  shifts:{title:"Shift Forge",icon:"⚒️",tag:"Realm II · Transform",description:"Move, stretch, and reflect familiar graphs without losing the parent.",color:"#ffd166"},
  rates:{title:"Rate Ridge",icon:"⚡",tag:"Realm III · Differentiate",description:"Connect slope, tangent lines, and motion in one clear picture.",color:"#ff8398"},
  factoring:{title:"Factor Foundry",icon:"🔧",tag:"Realm IV · Simplify",description:"Extract the GCF, spot patterns, group trinomials, and verify before limits.",color:"#8fb9ff"}
};
const STORAGE_KEY = "function-kingdom-138-v1";
function readProgress(){
  try{
    const raw=JSON.parse(localStorage.getItem(STORAGE_KEY)||"{}");
    const ids=new Set(QUESTIONS.map(q=>q.id));
    const fronts=new Set(FLASHCARDS.map(c=>c.front));
    const s=raw.session;
    const session=s&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.every(id=>ids.has(id))&&Number.isInteger(s.index)&&s.index>=0&&s.index<s.ids.length?{
      mode:typeof s.mode==="string"?s.mode:"review",ids:s.ids,index:s.index,correct:Number(s.correct)||0,earned:Number(s.earned)||0,
      wrong:Array.isArray(s.wrong)?s.wrong.filter(id=>ids.has(id)):[],answered:!!s.answered,selected:Number.isInteger(s.selected)?s.selected:-1,hint:!!s.hint
    }:null;
    return {xp:Number(raw.xp)||0,missed:Array.isArray(raw.missed)?raw.missed.filter(id=>ids.has(id)):[],best:raw.best&&typeof raw.best==="object"?raw.best:{},
      learned:Array.isArray(raw.learned)?raw.learned.filter(front=>fronts.has(front)):[],study:raw.study&&typeof raw.study==="object"?raw.study:{group:"All",index:0,flipped:false},session};
  }catch{return {xp:0,missed:[],best:{},learned:[],study:{group:"All",index:0,flipped:false},session:null}}
}
let progress=readProgress();
let state={view:"home",round:[],index:0,correct:0,earned:0,wrong:[],answered:false,selected:-1,hint:false,mode:"",studyGroup:"All",studyIndex:0,flipped:false};
const screen=document.getElementById("screen");
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"})[c]);
function save(){
  if(state.view==="play")progress.session={mode:state.mode,ids:state.round.map(q=>q.id),index:state.index,correct:state.correct,earned:state.earned,wrong:state.wrong,answered:state.answered,selected:state.selected,hint:state.hint};
  if(state.view==="study")progress.study={group:state.studyGroup,index:state.studyIndex,flipped:state.flipped};
  try{localStorage.setItem(STORAGE_KEY,JSON.stringify(progress))}catch{}
  document.getElementById("totalXp").textContent=`✦ ${progress.xp} XP`;
}
function randomize(items){const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function graphSvg(kind){
  if(kind==="quizG")return `<svg viewBox="0 0 420 270" role="img" aria-label="Quiz graph of g with a jump at x zero and three distinct points at x two"><rect x="38" y="23" width="350" height="217" fill="#101b30"/><g stroke="#344762" stroke-width="1">${[-2,-1,0,1,2,3,4].map(x=>`<path d="M${155+55*x} 23V240"/>`).join("")}${[-2,-1,0,1,2,3,4].map(y=>`<path d="M38 ${155-32*y}H388"/>`).join("")}</g><path d="M38 155H388 M155 23V240" stroke="#a6b7d2" stroke-width="2"/><path d="M45 95 C70 139 113 184 155 187" fill="none" stroke="#73e0c4" stroke-width="4"/><path d="M155 219 C193 220 204 124 265 91" fill="none" stroke="#73e0c4" stroke-width="4"/><path d="M265 155 C304 160 336 70 388 50" fill="none" stroke="#73e0c4" stroke-width="4"/><g fill="#101b30" stroke="#ffd166" stroke-width="3"><circle cx="155" cy="219" r="6"/><circle cx="265" cy="91" r="6"/><circle cx="265" cy="155" r="6"/></g><g fill="#ffd166"><circle cx="155" cy="187" r="6"/><circle cx="265" cy="123" r="6"/></g><g fill="#c7d5e8" font-size="13" font-family="system-ui"><text x="149" y="258">0</text><text x="260" y="258">2</text><text x="374" y="170">x</text><text x="163" y="35">y</text><text x="129" y="225">−2</text><text x="133" y="193">−1</text><text x="139" y="96">2</text><text x="274" y="91">2</text><text x="318" y="40">g(x)</text></g></svg>`;
  if(kind==="quizPair")return `<svg viewBox="0 0 700 270" role="img" aria-label="Paired Quiz 2 graphs of f and g, with holes and jumps"><rect x="20" y="20" width="315" height="215" fill="#101b30"/><rect x="365" y="20" width="325" height="215" fill="#101b30"/><g stroke="#344762" stroke-width="1">${[45,95,145,195,245,295,390,440,490,540,590,640,690].map(x=>`<path d="M${x} 20V235"/>`).join("")}${[60,95,130,165,200].map(y=>`<path d="M20 ${y}H335 M365 ${y}H690"/>`).join("")}</g><path d="M20 165H335 M145 20V235 M365 165H690 M490 20V235" stroke="#a6b7d2" stroke-width="2"/><path d="M25 200 C69 124 105 94 145 95 C194 94 213 159 245 200 C271 148 291 129 330 95" fill="none" stroke="#73e0c4" stroke-width="4"/><path d="M370 165 C410 91 453 57 490 60 M490 130 C531 130 559 119 590 95 L690 235" fill="none" stroke="#ffb782" stroke-width="4"/><g fill="#101b30" stroke="#ffd166" stroke-width="3"><circle cx="95" cy="130" r="5"/><circle cx="245" cy="200" r="6"/><circle cx="490" cy="130" r="6"/></g><g fill="#ffd166"><circle cx="95" cy="60" r="5"/><circle cx="490" cy="60" r="6"/></g><g fill="#d3deef" font-size="13" font-family="system-ui"><text x="145" y="254">0</text><text x="240" y="254">2</text><text x="292" y="254">3</text><text x="488" y="254">0</text><text x="586" y="254">2</text><text x="636" y="254">3</text><text x="260" y="42">f(x)</text><text x="608" y="42">g(x)</text></g></svg>`;
  if(kind==="position")return `<svg viewBox="0 0 420 260" role="img" aria-label="Position versus time: rises from 0 to 2 seconds, flat from 2 to 4, falls from 4 to 6"><defs><pattern id="grid" width="50" height="40" patternUnits="userSpaceOnUse"><path d="M 50 0 L 0 0 0 40" fill="none" stroke="#334460" stroke-width="1"/></pattern></defs><rect x="46" y="22" width="330" height="194" fill="url(#grid)"/><path d="M46 22V216H380" fill="none" stroke="#95a9c8" stroke-width="2"/><path d="M65 178 L165 72 L265 72 L365 178" fill="none" stroke="#73e0c4" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><g fill="#ffd166"><circle cx="65" cy="178" r="5"/><circle cx="165" cy="72" r="5"/><circle cx="265" cy="72" r="5"/><circle cx="365" cy="178" r="5"/></g><g fill="#b8c6df" font-size="13" font-family="system-ui"><text x="59" y="238">0</text><text x="159" y="238">2</text><text x="259" y="238">4</text><text x="359" y="238">6</text><text x="304" y="254">time (s)</text><text x="4" y="18">position</text></g></svg>`;
  const fns={sqrt:x=>x<0?NaN:Math.sqrt(x),square:x=>x*x,abs:x=>Math.abs(x),reciprocal:x=>Math.abs(x)<.1?NaN:1/x,exp:x=>Math.pow(2,x),expE:x=>Math.exp(x),log:x=>x<=0?NaN:Math.log(x),cubic:x=>x*x*x};
  const fn=fns[kind];if(!fn)return "";
  const X=x=>210+x*34,Y=y=>130-y*22;let paths=[],current="";
  for(let px=-5.2;px<=5.2;px+=.025){const py=fn(px);if(!Number.isFinite(py)||Math.abs(py)>5.1){if(current){paths.push(current);current=""}continue}const point=`${X(px).toFixed(1)} ${Y(py).toFixed(1)}`;current+=`${current?" L":"M"}${point}`}
  if(current)paths.push(current);
  const asym=kind==="reciprocal"?`<path d="M210 17V242 M27 130H393" stroke="#ff8398" stroke-dasharray="5 5" opacity=".5"/>`:kind==="log"?`<path d="M210 17V242" stroke="#ff8398" stroke-dasharray="5 5" opacity=".5"/>`:kind==="expE"?`<path d="M27 130H393" stroke="#ff8398" stroke-dasharray="5 5" opacity=".5"/>`:"";
  return `<svg viewBox="0 0 420 260" role="img" aria-label="Graph of ${escapeHtml(kind)} parent function on x and y axes"><defs><pattern id="grid" width="34" height="22" patternUnits="userSpaceOnUse"><path d="M 34 0 L 0 0 0 22" fill="none" stroke="#334460" stroke-width="1"/></pattern></defs><rect x="28" y="18" width="364" height="224" fill="url(#grid)"/><path d="M28 130H392 M210 18V242" stroke="#879abb" stroke-width="2"/>${asym}${paths.map(p=>`<path d="${p}" fill="none" stroke="#73e0c4" stroke-width="4" stroke-linecap="round"/>`).join("")}<g fill="#b8c6df" font-size="12" font-family="system-ui"><text x="390" y="124">x</text><text x="216" y="27">y</text><text x="215" y="145">0</text></g></svg>`
}
const heroSvg=`<svg viewBox="0 0 380 260" aria-hidden="true"><path d="M23 189H355 M188 26V236" stroke="#7286a6" stroke-width="2"/><path d="M46 198 C90 191 105 165 142 160 C175 155 177 126 201 112 C236 92 250 73 310 58" fill="none" stroke="#73e0c4" stroke-width="6" stroke-linecap="round"/><path d="M105 188 L284 89" stroke="#ffd166" stroke-width="4" stroke-dasharray="8 8"/><circle cx="194" cy="139" r="9" fill="#ffd166"/><text x="216" y="136" fill="#ffd166" font-size="16" font-family="Georgia">tangent slope</text><text x="326" y="210" fill="#9bb0cf" font-size="15">x</text><text x="199" y="38" fill="#9bb0cf" font-size="15">y</text></svg>`;
function home(){state.view="home";save();screen.innerHTML=`<section class="hero"><div><div class="eyebrow">Your two-day calculus warmup</div><h1>Enter the<br><em>Function Kingdom.</em></h1><p>Recognize the parent. Move the graph. Factor the expression. Read the slope. Every answer comes with the reason, so you can use the idea again on your exam.</p><div class="button-row"><button class="primary" data-action="start" data-mode="sprint">Start 12-question sprint →</button><button class="secondary" data-action="study">Open memory dojo</button>${progress.session?`<button class="secondary" data-action="resume">Resume round · question ${progress.session.index+1}/${progress.session.ids.length}</button>`:""}</div></div><div class="hero-art">${heroSvg}<span class="art-label">FROM CURVE TO TANGENT</span></div></section><section><div class="section-heading"><div><h2>Choose a realm</h2><p>Short rounds by topic. Practice as often as you need.</p></div>${progress.missed.length?`<button class="small-button" data-action="start" data-mode="review">Review ${progress.missed.length} missed ↗</button>`:""}</div><div class="mission-grid">${Object.entries(REALMS).map(([key,r])=>`<article class="mission"><div class="mission-icon">${r.icon}</div><div class="tag">${r.tag}</div><h3>${r.title}</h3><p>${r.description}</p><button class="small-button" data-action="start" data-mode="${key}">Enter realm →</button></article>`).join("")}</div></section><aside class="memo"><span class="memo-icon">🧠</span><div><b>Memory trail: Flat → Line → Bowl → Root → V → S → Sideways S → Rocket → Log → Split</b><p>Constant, identity, quadratic, square root, absolute value, cubic, cube root, exponential, logarithm, reciprocal. For factoring, remember G → P → C: GCF, Pattern, Check.</p></div></aside>`;screen.focus()}
function factoringLesson(){state.view="lesson";screen.innerHTML=`<section class="lesson"><div class="eyebrow">🔧 Factor Foundry · Quick lesson</div><h1>Factor in a dependable order.</h1><p>Factoring rewrites a sum as a product. That makes hidden common factors visible in calculus expressions, especially when direct substitution gives 0/0.</p><ol class="lesson-steps"><li><b>1 · GCF first</b><span>6x² + 9x = <strong>3x(2x + 3)</strong>. Take out what every term shares.</span></li><li><b>2 · Spot the pattern</b><span>x² − 25 = <strong>(x − 5)(x + 5)</strong>. For x² + bx + c, seek a pair with product c and sum b.</span></li><li><b>3 · When a ≠ 1</b><span>For 2x² + 7x + 3, product ac = 6 and sum b = 7. Split 7x into 6x + x, then group.</span></li><li><b>4 · Multiply back</b><span>(2x + 1)(x + 3) = 2x² + 7x + 3. In a quotient, cancel a full common factor, never just a term.</span></li></ol><div class="button-row"><button class="primary" data-action="launch" data-mode="factoring">Practice the path →</button><button class="secondary" data-action="study" data-group="Factoring">See factoring cards</button><button class="secondary" data-action="home">Mission board</button></div></section>`;screen.focus()}
function quizLesson(){state.view="lesson";screen.innerHTML=`<section class="lesson"><div class="eyebrow">🧭 Quiz 2 Recovery · Guided checkpoints</div><h1>Read the evidence before calculating.</h1><p>These vector graphs and exercises are adapted from the four supplied photos of your Quiz 2. Pick one short checkpoint or play the complete recovery run.</p><div class="checkpoint-grid"><button class="checkpoint" data-action="launch" data-mode="quiz:graph"><b>1 · Graph detective</b><span>8 prompts · left, right, two-sided, and filled points at x = 0 and 2.</span></button><button class="checkpoint" data-action="launch" data-mode="quiz:laws"><b>2 · Limit laws</b><span>4 prompts · read f and g first, then combine their limits.</span></button><button class="checkpoint" data-action="launch" data-mode="quiz:methods"><b>3 · Pick a method</b><span>4 prompts · substitute, rationalize, factor, or identify oscillation.</span></button><button class="checkpoint" data-action="launch" data-mode="quiz:parents"><b>4 · Sketch anchors</b><span>4 prompts · x², eˣ, 1/x, and ln x with intercepts and asymptotes.</span></button></div><div class="button-row"><button class="primary" data-action="launch" data-mode="quiz">Full 20-question recovery →</button><button class="secondary" data-action="study" data-group="Quiz 2">Quiz 2 cards</button><button class="secondary" data-action="home">Mission board</button></div></section>`;screen.focus()}
function notesLesson(){state.view="lesson";screen.innerHTML=`<section class="lesson"><div class="eyebrow">📓 Notes Lab · From class to practice</div><h1>Choose the method from the signal.</h1><p>Turn the handwritten notes into a repeatable decision route. Work a short checkpoint, then explain the move before checking the answer.</p><ol class="lesson-steps"><li><b>1 · Approach or point?</b><span>On a graph or piecewise rule, separate the nearby value from f(a). Check left and right if a jump is possible.</span></li><li><b>2 · Substitute first</b><span>For continuous polynomials and rational expressions with a nonzero denominator, evaluate directly.</span></li><li><b>3 · Repair 0/0</b><span>Factor a polynomial or rationalize a radical; cancel only a complete common factor.</span></li><li><b>4 · Inspect behavior</b><span>Oscillation may mean DNE unless shrinking bounds squeeze it. At infinity, compare leading terms; near vertical asymptotes, inspect signs.</span></li></ol><div class="checkpoint-grid"><button class="checkpoint" data-action="launch" data-mode="notes:approach"><b>Approach versus point</b><span>5 prompts · holes, direct substitution, absolute value sides.</span></button><button class="checkpoint" data-action="launch" data-mode="notes:repair"><b>Repair a 0/0 form</b><span>4 prompts · factors, conjugates, and method choice.</span></button><button class="checkpoint" data-action="launch" data-mode="notes:behavior"><b>Behavior and infinity</b><span>6 prompts · squeeze, asymptotes, dominant terms, oscillation.</span></button><button class="checkpoint" data-action="launch" data-mode="notes:tangent"><b>From secant to tangent</b><span>4 prompts · first principles and the line at x = 3.</span></button></div><div class="button-row"><button class="primary" data-action="launch" data-mode="notes">Full notes run →</button><button class="secondary" data-action="study" data-group="Class Notes">Class-note cards</button><button class="secondary" data-action="home">Mission board</button></div></section>`;screen.focus()}
function start(mode){if(mode==="factoring"){factoringLesson();return}if(mode==="quiz"){quizLesson();return}if(mode==="notes"){notesLesson();return}launch(mode)}
function launch(mode){let round;if(mode==="sprint")round=[...randomize(QUESTIONS.filter(q=>q.realm==="parents")).slice(0,3),...randomize(QUESTIONS.filter(q=>q.realm==="shifts")).slice(0,3),...randomize(QUESTIONS.filter(q=>q.realm==="factoring")).slice(0,3),...randomize(QUESTIONS.filter(q=>q.realm==="rates")).slice(0,3)];else if(mode==="review")round=progress.missed.map(id=>QUESTIONS.find(q=>q.id===id)).filter(Boolean);else if(mode.startsWith("quiz:")||mode.startsWith("notes:")){const [realm,stage]=mode.split(":");round=QUESTIONS.filter(q=>q.realm===realm&&q.stage===stage)}else round=QUESTIONS.filter(q=>q.realm===mode);if(!round.length){home();return}state={...state,view:"play",round,index:0,correct:0,earned:0,wrong:[],answered:false,selected:-1,hint:false,mode};renderQuestion()}
function resumeRound(){
  const saved=progress.session;
  if(!saved){home();return}
  state={...state,view:"play",round:saved.ids.map(id=>QUESTIONS.find(q=>q.id===id)),index:saved.index,correct:saved.correct,earned:saved.earned,
    wrong:[...saved.wrong],answered:saved.answered,selected:saved.selected,hint:saved.hint,mode:saved.mode};
  renderQuestion();
}
function renderQuestion(){save();const q=state.round[state.index],total=state.round.length,realm=REALMS[q.realm];state.view="play";screen.innerHTML=`<div class="play-layout"><div class="play-top"><span><strong>${realm.icon} ${realm.title}</strong> · ${state.mode==="sprint"?"Exam Sprint":state.mode==="review"?"Missed review":state.mode.startsWith("quiz:")?"Quiz checkpoint":"Realm round"}</span><span>Question ${state.index+1} / ${total} · ${state.correct} correct</span></div><div class="progress-track" role="progressbar" aria-label="Round progress" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${state.index}"><div class="progress-fill" style="width:${state.index/total*100}%"></div></div><article class="question-card"><div class="question-label">${realm.tag}</div><h1>${q.prompt}</h1><p class="context">${q.context}</p>${q.graph?`<div class="graph-wrap ${q.graph==="quizPair"?"wide":""}">${graphSvg(q.graph)}<div class="graph-caption">${q.graph==="position"?"Position against time · read the slope of each segment":q.graph==="quizG"?"Quiz 2 graph of g · open circles are approached values; solid dots are function values":q.graph==="quizPair"?"Quiz 2 graphs of f and g · each grid square is one unit":"Parent-function graph · axes cross at the origin"}</div></div>`:""}<div class="choices" role="group" aria-label="Answer choices">${q.options.map((o,i)=>`<button class="choice ${state.answered?(i===q.answer?"correct":i===state.selected?"wrong":""):""}" data-action="answer" data-index="${i}" ${state.answered?"disabled":""}><span class="key">${String.fromCharCode(65+i)}</span><span>${o}</span></button>`).join("")}</div><div class="question-tools"><button class="hint" data-action="hint" ${state.answered?"disabled":""}>${state.hint?"Hint revealed":"Need a hint? (H)"}</button><button class="exit" data-action="home">Leave round</button></div>${state.hint&&!state.answered?`<div class="hint-box">${q.hint}</div>`:""}${state.answered?`<div class="feedback ${state.selected===q.answer?"good":"bad"}" role="status"><strong>${state.selected===q.answer?"✓ Correct. Nice connection.":"↻ Keep this one for review."}</strong><p>${q.explanation}</p><div class="takeaway">REMEMBER · ${q.takeaway}</div></div><div class="next-row"><button class="primary" data-action="next">${state.index===total-1?"See round results →":"Next question →"}</button></div>`:""}</article></div>`;screen.focus()}
function answer(i){if(state.view!=="play"||state.answered||!Number.isInteger(i)||i<0||i>3)return;const q=state.round[state.index];state.answered=true;state.selected=i;if(i===q.answer){state.correct++;const points=state.hint?7:10;state.earned+=points;progress.xp+=points;progress.missed=progress.missed.filter(id=>id!==q.id)}else{state.wrong.push(q.id);if(!progress.missed.includes(q.id))progress.missed.push(q.id)}save();renderQuestion()}
function next(){if(!state.answered)return;if(state.index<state.round.length-1){state.index++;state.answered=false;state.selected=-1;state.hint=false;renderQuestion()}else results()}
function results(){state.view="results";progress.session=null;const total=state.round.length,percent=Math.round(100*state.correct/total),label=percent===100?"A clear victory!":percent>=70?"The kingdom is opening.":"Your map is getting clearer.";const key=state.mode;progress.best[key]=Math.max(progress.best[key]||0,percent);save();screen.innerHTML=`<section class="result-card"><div class="result-icon">${percent===100?"🏆":percent>=70?"✨":"🧭"}</div><div class="eyebrow">Round complete</div><h1>${label}</h1><p>You got ${state.correct} of ${total} right. The explanations are part of the lesson; revisit any idea that did not stick.</p><div class="stat-row"><div class="stat"><b>${percent}%</b><span>this round</span></div><div class="stat"><b>+${state.earned}</b><span>XP earned</span></div><div class="stat"><b>${progress.missed.length}</b><span>cards to review</span></div></div><div class="button-row result-actions"><button class="primary" data-action="start" data-mode="${key}">Play again ↻</button>${progress.missed.length?`<button class="secondary" data-action="start" data-mode="review">Review missed</button>`:""}<button class="secondary" data-action="study">Study cards</button><button class="secondary" data-action="home">Mission board</button></div>${state.wrong.length?`<ul class="review-list"><li><strong>Missed this round</strong></li>${state.wrong.map(id=>{const q=QUESTIONS.find(x=>x.id===id);return `<li>${q.prompt} · ${q.takeaway}</li>`}).join("")}</ul>`:""}</section>`;screen.focus()}
function cardsForGroup(){return state.studyGroup==="All"?FLASHCARDS:FLASHCARDS.filter(c=>c.group===state.studyGroup)}
function study(group){const saved=progress.study||{group:"All",index:0,flipped:false};const chosen=group||saved.group||"All";const same=chosen===saved.group;state.view="study";state.studyGroup=chosen;state.studyIndex=same?Math.max(0,Math.min(Number(saved.index)||0,cardsForGroupLength(chosen)-1)):0;state.flipped=same&&!!saved.flipped;renderStudy()}
function cardsForGroupLength(group){return group==="All"?FLASHCARDS.length:FLASHCARDS.filter(c=>c.group===group).length}
function renderStudy(){save();const cards=cardsForGroup(),card=cards[state.studyIndex];screen.innerHTML=`<section class="study-header"><div class="eyebrow">Memory Dojo</div><h1>Build a picture you can recall.</h1><p>Flip each card, say the answer aloud, then mark anything you want to practice. The deck is organized by concept and can grow with your course.</p><div class="study-controls">${["All","Parents","Shifts","Factoring","Rates","Quiz 2","Class Notes"].map(g=>`<button class="chip ${state.studyGroup===g?"active":""}" data-action="filter" data-group="${g}">${g}</button>`).join("")}</div></section><section class="study-panel">${card?`<div class="study-count">${card.group} · Card ${state.studyIndex+1} of ${cards.length} · ${cards.filter(c=>progress.learned.includes(c.front)).length} learned</div><button class="flashcard" data-action="flip" aria-label="Flip flashcard"><span class="face-label">${state.flipped?"Answer":"Recall first"}</span><span class="face-text">${state.flipped?card.back:card.front}</span><span class="face-note">${state.flipped?"Click to see the prompt again":"Click or press Space to flip"}</span></button><div class="study-actions"><button class="secondary" data-action="prev">← Previous</button><button class="small-button" data-action="learned">${progress.learned.includes(card.front)?"✓ Learned":"Mark learned"}</button><button class="small-button" data-action="mark" aria-label="Add related question to missed review">${progress.missed.includes(card.question)?"✓ In review queue":"+ Practice this idea"}</button><button class="primary" data-action="studyNext">Next card →</button></div><p class="study-tip">The practice button adds a related question to your missed review queue. Cards cycle, so you can keep drilling.</p>`:`<div class="empty-state">No cards in this group yet.</div>`}</section>`;screen.focus()}
screen.addEventListener("click",e=>{const b=e.target.closest("button[data-action]");if(!b)return;switch(b.dataset.action){case"home":home();break;case"start":start(b.dataset.mode);break;case"resume":resumeRound();break;case"launch":launch(b.dataset.mode);break;case"study":study(b.dataset.group||"All");break;case"answer":answer(Number(b.dataset.index));break;case"next":next();break;case"hint":if(!state.answered){state.hint=true;renderQuestion()}break;case"filter":study(b.dataset.group);break;case"flip":state.flipped=!state.flipped;renderStudy();break;case"prev":state.studyIndex=(state.studyIndex-1+cardsForGroup().length)%cardsForGroup().length;state.flipped=false;renderStudy();break;case"studyNext":state.studyIndex=(state.studyIndex+1)%cardsForGroup().length;state.flipped=false;renderStudy();break;case"learned":{const front=cardsForGroup()[state.studyIndex].front;progress.learned=progress.learned.includes(front)?progress.learned.filter(x=>x!==front):[...progress.learned,front];renderStudy();break}case"mark":{const q=cardsForGroup()[state.studyIndex].question;if(!progress.missed.includes(q))progress.missed.push(q);save();renderStudy();break}}});
document.getElementById("homeButton").addEventListener("click",home);document.getElementById("studyNav").addEventListener("click",()=>study());
document.addEventListener("keydown",e=>{if(e.altKey||e.ctrlKey||e.metaKey||["INPUT","TEXTAREA"].includes(document.activeElement?.tagName))return;if(state.view==="play"){const key=e.key.toLowerCase();const index=/^[1-4]$/.test(key)?Number(key)-1:["a","b","c","d"].indexOf(key);if(index>=0){answer(index);return}if(key==="h"&&!state.answered){state.hint=true;renderQuestion()}if(key==="enter"&&state.answered)next()}else if(state.view==="study"&&e.code==="Space"){e.preventDefault();state.flipped=!state.flipped;renderStudy()}});
home();
if(typeof window!=="undefined"&&typeof navigator!=="undefined"&&"serviceWorker" in navigator){
  window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js").catch(()=>{}));
}
